if(current_user()) redirect(current_user()['role']==='admin'?'admin/index.php':'pages/dashboard.php');
$errors=[];$values=['full_name'=>'','email'=>''];
if($_SERVER['REQUEST_METHOD']==='POST') {
    require_csrf();[$errors,$values,$password]=validate_registration($_POST);
    if(!$errors) {
        try {query('INSERT INTO users(full_name,email,password_hash,role) VALUES (?,?,?,?)',[$values['full_name'],$values['email'],password_hash($password,PASSWORD_DEFAULT),'patient']);flash('Your account is ready. Sign in to start your care journey.');redirect('auth/login.php');}
        catch(PDOException $error) {if($error->getCode()==='23000') $errors['email']='An account with this email already exists. Please sign in.';else throw $error;}
    }
    if($errors)http_response_code(422);
}
$pageTitle='Create an account | Wellnest Medical Clinic';require __DIR__.'/../components/head.php';require __DIR__.'/../components/header.php';
